using System.ComponentModel;
using System.Net.Http.Json;
using System.Text.Json;
using Microsoft.Extensions.Logging;
using ModelContextProtocol.Server;

namespace McpServer.Tools;

[McpServerToolType]
public sealed class FetchPostTool
{
    [McpServerTool("fetch_post"), Description("Fetches a post from the external API by ID.")]
    public static async Task<string> FetchPostAsync(
        IHttpClientFactory httpClientFactory,
        ILogger<FetchPostTool> logger,
        [Description("The numeric ID of the post to fetch (1-100).")] int postId)
    {
        logger.LogInformation("Fetching post {PostId}", postId);

        var client = httpClientFactory.CreateClient("ExternalApi");
        var response = await client.GetAsync($"posts/{postId}");

        if (!response.IsSuccessStatusCode)
        {
            logger.LogWarning("API returned {StatusCode} for post {PostId}", response.StatusCode, postId);
            return $"Error: API returned {(int)response.StatusCode} {response.ReasonPhrase}";
        }

        var json = await response.Content.ReadFromJsonAsync<JsonElement>();
        return JsonSerializer.Serialize(json, new JsonSerializerOptions { WriteIndented = true });
    }
}

