+using System.ComponentModel;
+using ModelContextProtocol.Server;
+
+namespace McpServer.Prompts;
+
+[McpServerPromptType]
+public sealed class SummarizePrompt
+{
+    [McpServerPrompt("summarize"), Description("Generates a prompt that asks an LLM to summarize the given text.")]
+    public static IEnumerable<ChatMessage> Summarize(
+        [Description("The text content to summarize.")] string text,
+        [Description("Optional maximum number of sentences for the summary.")] string? maxSentences = null)
+    {
+        var instruction = maxSentences is not null
+            ? $"Summarize the following text in at most {maxSentences} sentences. Be concise and capture the key points."
+            : "Summarize the following text concisely, capturing the key points.";
+
+        yield return new ChatMessage(ChatMessageRole.User, $"{instruction}\n\n---\n\n{text}");
+    }
+}
